using GpSelect.Application; using GpSelect.Domain; using GpSelect.Infrastructure; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace GpSelect.Api;
[ApiController][Route("api/admin/vehicles")][Authorize(Roles="Admin")] public class VehiclesController(GpSelectDbContext db,ISlugGenerator slugs,IObjectStorage storage):ControllerBase { private List<ImageAdminDto> Images(VehicleUnit v)=>db.Images.Where(x=>x.VehicleUnitId==v.Id).OrderBy(x=>x.SortOrder).Select(x=>new ImageAdminDto(x.Id,x.State,x.State==ImageState.Ready?$"/api/admin/vehicles/{v.Id}/images/{x.Id}/card":null,x.State==ImageState.Ready?$"/api/admin/vehicles/{v.Id}/images/{x.Id}/detail":null,x.IsCover,x.SortOrder,x.FailureReason)).ToList(); private VehicleAdminListDto MapList(VehicleUnit v)=>new(v.Id,v.PublicSlug,v.Status,v.Make,v.Model,v.FirstRegistrationYear,v.FirstRegistrationMonth,v.PriceEur,v.InternalReference,Images(v)); private VehicleAdminDto Map(VehicleUnit v)=>new(v.Id,v.PublicSlug,v.Status,v.Make,v.Model,v.FirstRegistrationYear,v.FirstRegistrationMonth,v.PriceEur,v.InternalReference,v.Description,v.MileageKm,v.Variant,v.FuelType,v.Transmission,v.BodyType,v.ExteriorColour,v.Interior,v.History,v.Provenance,v.EquipmentJson,v.CustomSpecificationsJson,Images(v)); [HttpGet] public async Task<IResult> List()=>Results.Ok((await db.Vehicles.AsNoTracking().ToListAsync()).Select(MapList)); [HttpGet("{id:guid}")] public async Task<IActionResult> Get(Guid id){var v=await db.Vehicles.FindAsync(id);return v is null?NotFound():Ok(Map(v));} [HttpPost] public async Task<IActionResult> Create(CreateVehicleRequest r){try{var v=VehicleUnit.Create(r.Make,r.Model,r.FirstRegistrationYear,r.FirstRegistrationMonth,slugs.Generate(r.Make,r.Model)); db.Vehicles.Add(v);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=v.Id},Map(v));}catch(DomainException e){return Problem(statusCode:400,title:e.Message);}} [HttpPatch("{id:guid}")] public async Task<IActionResult> Update(Guid id,UpdateVehicleRequest r){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();try{v.Update(r.Make,r.Model,r.FirstRegistrationYear,r.FirstRegistrationMonth,r.PriceEur,r.Description,r.InternalReference,r.MileageKm,r.Variant,r.FuelType,r.Transmission,r.BodyType,r.ExteriorColour,r.Interior,r.History,r.Provenance,r.EquipmentJson,r.CustomSpecificationsJson);await db.SaveChangesAsync();return Ok(Map(v));}catch(DomainException e){return Problem(statusCode:400,title:e.Message);}} [HttpPost("{id:guid}/publish")] public async Task<IActionResult> Publish(Guid id,[FromBody] PublishRequest? request){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();try{v.Publish(await db.Images.Where(x=>x.VehicleUnitId==id).ToListAsync(),request?.Target??VehicleStatus.ComingSoon);await db.SaveChangesAsync();return Ok(Map(v));}catch(DomainException e){return Problem(statusCode:422,title:e.Message);}} [HttpPost("{id:guid}/archive")] public async Task<IActionResult> Archive(Guid id){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();v.Archive();await db.SaveChangesAsync();return NoContent();} [HttpGet("{id:guid}/preview")] public async Task<IActionResult> Preview(Guid id){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();Response.Headers["X-Robots-Tag"]="noindex, nofollow";var dto=PublicMapping.Map(v,await db.Images.Where(x=>x.VehicleUnitId==id).ToListAsync());return Ok(dto with {Images=dto.Images.Select(x=>x.Replace($"/api/public/vehicles/{Uri.EscapeDataString(v.PublicSlug)}/images/",$"/api/admin/vehicles/{v.Id}/preview/images/")).ToList()});} [HttpGet("{id:guid}/preview/images/{imageId:guid}/detail")] public async Task<IActionResult> PreviewImage(Guid id,Guid imageId){var image=await db.Images.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==imageId&&x.VehicleUnitId==id&&x.State==ImageState.Ready);if(image is null||image.DetailKey is null)return NotFound();return File(await storage.OpenReadAsync(image.DetailKey,HttpContext.RequestAborted),"image/jpeg");} }


public sealed record PublishRequest(VehicleStatus Target);




